    const s = document.createElement("script");
    s.src = "https://www.google.com/recaptcha/api.js?render=" + encodeURIComponent(SITE_KEY);
    s.async = true;
    s.defer = true;
    document.head.appendChild(s);

    document.addEventListener("DOMContentLoaded", () => {
        let tries = 0;
        const maxTries = 50; // ~5 seconds
        const timer = setInterval(() => {
            tries++;
            const b = document.querySelector(".grecaptcha-badge");
            if (b) {
                b.style.visibility = "visible";
                clearInterval(timer);
            }
            if (tries >= maxTries) clearInterval(timer);
        }, 100);
    });
})();

body.script:
(function () {
    // install only once (prevents duplicates if header is included multiple times)
    if (window.__recaptchaSubmitInstalled) return;
    window.__recaptchaSubmitInstalled = true;

    const SITE_KEY = "6LcpX0ksAAAAAMGG9Typ4Y7x1bMb747hoAVap-T5";
    const ACTION   = "domain_check";

    function getRecaptchaApi() {
        const g = window.grecaptcha;
        if (!g) return null;
        // If enterprise.js is used:
        if (g.enterprise && typeof g.enterprise.execute === "function") return g.enterprise;
        // Standard v3:
        if (typeof g.execute === "function") return g;
        return null;
    }

    async function getToken() {
        const api = getRecaptchaApi();
        if (!api) throw new Error("grecaptcha not loaded (blocked or wrong script)");

        // Some variants have ready(); standard v3 has it.
        if (typeof api.ready === "function") {
            await new Promise(res => api.ready(res));
        }
        return api.execute(SITE_KEY, { action: ACTION });
    }

    document.addEventListener("submit", async (e) => {
        const form = e.target;
        if (!(form instanceof HTMLFormElement)) return;

        // Match action reliably (handles /pirkti_test.php, pirkti_test.php, absolute URLs)
        const actionAttr = (form.getAttribute("action") || "").trim();
        const actionAbs  = (form.action || "");
        const isPirkti = actionAttr.endsWith("tikrinti_test.php") || actionAbs.endsWith("/tikrinti_test.php") || actionAttr.endsWith("tikrinti.php") || actionAbs.endsWith("/tikrinti.php");
        if (!isPirkti) return;

        // If we already injected a token for this submit, allow normal submit
        if (form.dataset.recaptchaDone === "1") return;

        // Prevent multiple parallel handlers
        if (form.dataset.recaptchaBusy === "1") {
            e.preventDefault();
            return;
        }
        form.dataset.recaptchaBusy = "1";

        // Stop submit until token is injected
        e.preventDefault();

        try {
            const token = await getToken();

            // Ensure hidden inputs exist
            let tok = form.querySelector('input[name="recaptcha_token"]');
            console.log(tok);
            if (!tok) {
                tok = document.createElement("input");
                tok.type = "hidden";
                tok.name = "recaptcha_token";
                form.appendChild(tok);
            }

            let act = form.querySelector('input[name="recaptcha_action"]');
            console.log(act);
            if (!act) {
                act = document.createElement("input");
                act.type = "hidden";
                act.name = "recaptcha_action";
                form.appendChild(act);
            }

            tok.value = token;
            act.value = ACTION;

            // Mark as done so resubmit doesn't loop
            form.dataset.recaptchaDone = "1";

            // Preserve the original submitter (important for formnovalidate buttons)
            const submitter = e.submitter instanceof HTMLElement ? e.submitter : null;

            // Resubmit normally
            if (submitter && typeof form.requestSubmit === "function") {
                form.requestSubmit(submitter);
            } else if (typeof form.requestSubmit === "function") {
                form.requestSubmit();
            } else {
                // Old browsers fallback (won't fire submit event, but we already injected token)
                form.submit();
            }
        } catch (err) {
            console.error("reCAPTCHA failed:", err);
            form.dataset.recaptchaBusy = "0";
            // optional: show message
            // alert("reCAPTCHA error. Please disable blockers and try again.");
        }
    }, true);
})();

footer.script:
function setCookie(name, value, hours) {
    var expires = "";
    if (hours) {
        var date = new Date();
        date.setTime(date.getTime() + (hours * 60 * 60 * 1000));
        expires = "; expires=" + date.toUTCString();
    }
    document.cookie = name + "=" + (value || "") + expires + "; path=/; domain=iv.lt";
}

const urlParams = new URLSearchParams(window.location.search);
const transID = urlParams.get('t');

if (transID) {
    setCookie('transID', transID, 1);
}

body.script:
async function checkStatus() {
    try {
        const response = await fetch('https://paslaugos.iv.lt/intercom.php?type=intercom_chat_lt');
        const text = await response.text();
        const result = JSON.parse(text);
        let status = result.status === 'yes';
        if (status) {
            showIntercom();
        }
    } catch (error) {
        console.error('Error fetching status:', error);
    }
}

checkStatus();

function showIntercom() {
    // ===================
    // CONFIG (GUEST MODE)
    // ===================
    const APP_ID = "vwhwt4d6";
    const COOKIE_DOMAIN = ".iv.lt"; // <-- CHANGE THIS (share across root + subdomain)
    const GUEST_SESSION_MINUTES = 15;

    const GUEST_UID_COOKIE = "iv_intercom_uid";
    const GUEST_UID_MAX_AGE_SECONDS = GUEST_SESSION_MINUTES * 60;
    const INTERCOM_SESSION_DURATION_MS = GUEST_SESSION_MINUTES * 60 * 1000;

    let intercomLoaded = false;
    let intercomBooted = false;
    let idleTimer = null;

    const startedAt = performance.now();

    function getCookie(name) {
        const match = document.cookie.match(new RegExp("(?:^|; )" + name + "=([^;]*)"));
        return match ? decodeURIComponent(match[1]) : null;
    }

    function setCookie(name, value, maxAgeSeconds) {
        const secure = location.protocol === "https:" ? "; Secure" : "";
        document.cookie =
            `${name}=${encodeURIComponent(value)}` +
            `; Max-Age=${maxAgeSeconds}` +
            `; Path=/` +
            `; Domain=${COOKIE_DOMAIN}` +
            `; SameSite=Lax` +
            secure;
    }

    function deleteCookie(name) {
        const secure = location.protocol === "https:" ? "; Secure" : "";
        document.cookie =
            `${name}=` +
            `; Max-Age=0` +
            `; Path=/` +
            `; Domain=${COOKIE_DOMAIN}` +
            `; SameSite=Lax` +
            secure;
    }

    function clearIntercomCookies() {
        deleteCookie(`intercom-id-${APP_ID}`);
        deleteCookie(`intercom-session-${APP_ID}`);
    }

    if (!getCookie(GUEST_UID_COOKIE)) {
        clearIntercomCookies();
    }

    function generateId() {
        return (crypto.randomUUID
                ? crypto.randomUUID()
                : "iv_" + Math.random().toString(36).slice(2) + Date.now().toString(36)
        );
    }

    function getOrCreateGuestId() {
        const existing = getCookie(GUEST_UID_COOKIE);
        if (existing) return existing;

        clearIntercomCookies();

        const id = generateId();
        setCookie(GUEST_UID_COOKIE, id, GUEST_UID_MAX_AGE_SECONDS);
        return id;
    }

    function shutdownForPrivacy() {
        if (typeof window.Intercom === "function") {
            try { window.Intercom("shutdown"); } catch (e) {}
        }
        deleteCookie(GUEST_UID_COOKIE);
        clearIntercomCookies();

        intercomLoaded = false;
        intercomBooted = false;
    }

    function resetIdleTimer(guestId) {
        setCookie(GUEST_UID_COOKIE, guestId, GUEST_UID_MAX_AGE_SECONDS);

        if (idleTimer) clearTimeout(idleTimer);
        idleTimer = setTimeout(shutdownForPrivacy, INTERCOM_SESSION_DURATION_MS);
    }

    function isRealUserEvent(e) {
        if (e && e.isTrusted === false) return false;
        if (performance.now() - startedAt < 1500) return false;
        return true;
    }

    function getParam(param) {
        const urlParams = new URLSearchParams(window.location.search);
        return urlParams.get(param);
    }

    function ensureIntercomScriptLoaded() {
        if (window.__ivIntercomScriptInjected) return;
        window.__ivIntercomScriptInjected = true;

        const d = document;
        const s = d.createElement("script");
        s.type = "text/javascript";
        s.async = true;
        s.src = "https://widget.intercom.io/widget/" + APP_ID;
        s.setAttribute("data-no-optimize", "1");
        (d.head || d.body).appendChild(s);
    }

    function loadIntercomForRealUser(e) {
        if (!isRealUserEvent(e)) return;

        if (intercomLoaded && intercomBooted) {
            const gid = getCookie(GUEST_UID_COOKIE) || getOrCreateGuestId();
            resetIdleTimer(gid);
            return;
        }

        intercomLoaded = true;

        const guestUserId = getOrCreateGuestId();

        window.intercomSettings = {
            api_base: "https://api-iam.eu.intercom.io",
            app_id: APP_ID,
            brand: "Interneto vizija",
            language_override: "lt",

            user_id: guestUserId,

            session_duration: INTERCOM_SESSION_DURATION_MS
        };

        if (typeof window.Intercom !== "function") {
            const i = function () { i.c(arguments); };
            i.q = [];
            i.c = function (args) { i.q.push(args); };
            window.Intercom = i;
        }

        ensureIntercomScriptLoaded();

        if (!intercomBooted) {
            window.Intercom("boot", window.intercomSettings);
            intercomBooted = true;
        } else {
            window.Intercom("update", window.intercomSettings);
        }

        resetIdleTimer(guestUserId);

        document.addEventListener("visibilitychange", () => {
            if (!document.hidden) {
                const gid = getCookie(GUEST_UID_COOKIE) || getOrCreateGuestId();
                if (typeof window.Intercom === "function") {
                    window.Intercom("update", window.intercomSettings);
                }
                resetIdleTimer(gid);
            }
        });

        window.addEventListener("focus", () => {
            const gid = getCookie(GUEST_UID_COOKIE) || getOrCreateGuestId();
            if (typeof window.Intercom === "function") {
                window.Intercom("update", window.intercomSettings);
            }
            resetIdleTimer(gid);
        });

        ["pointerdown", "keydown", "click", "scroll", "touchstart", "mousemove"].forEach(evtName => {
            window.addEventListener(evtName, (evt) => {
                if (!isRealUserEvent(evt)) return;
                const gid = getCookie(GUEST_UID_COOKIE);
                if (gid) resetIdleTimer(gid);
            }, { passive: true });
        });

        if (getParam("openChat") === "true") {
            setTimeout(() => {
                if (typeof window.Intercom === "function") window.Intercom("show");
            }, 800);
        }
    }

    function onScroll(e) {
        if (!isRealUserEvent(e)) return;
        if ((window.scrollY || 0) < 120) return;
        loadIntercomForRealUser(e);
    }

    function onMouseMove(e) {
        if (!isRealUserEvent(e)) return;
        if ((Math.abs(e.movementX) + Math.abs(e.movementY)) < 8) return;
        loadIntercomForRealUser(e);
    }

    window.addEventListener("pointerdown", loadIntercomForRealUser, { passive: true });
    window.addEventListener("keydown", loadIntercomForRealUser);
    window.addEventListener("touchstart", loadIntercomForRealUser, { passive: true });
    window.addEventListener("mousemove", onMouseMove, { passive: true });
    window.addEventListener("scroll", onScroll, { passive: true });
}

